import unittest
from limits import parse_memory_limit

class MemoryLimitTests(unittest.TestCase):
    def test_plain_bytes(self):
        self.assertEqual(parse_memory_limit("2048 B"), 2048)
    def test_binary_units_and_spacing(self):
        self.assertEqual(parse_memory_limit("8 GiB"), 8 * 1024**3)
        self.assertEqual(parse_memory_limit("512MiB"), 512 * 1024**2)
    def test_decimal_unit_case_insensitive(self):
        self.assertEqual(parse_memory_limit("1.5 gb"), 1_500_000_000)
    def test_invalid_input_is_clear(self):
        for value in ("many gigabytes", "-1 GB", ""):
            with self.subTest(value=value), self.assertRaises(ValueError):
                parse_memory_limit(value)

